tool.command:

  ln -f -s ${input_matrix_path} ${input_matrix_path}_`echo $$`.${input_matrix_path.ext};

  ln -f -s ${input_top_path} ${input_top_path}_`echo $$`.${input_top_path.ext};

  ln -f -s ${input_contact_matrix_path} ${input_contact_matrix_path}_`echo $$`.${input_contact_matrix_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

create_graph

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__selection__dq__:__dq__${properties.selection}__dq__,__dq__corr_threshold__dq__:${properties.corr_threshold},__dq__use_abs__dq__:${properties.use_abs},__dq__loc_factor__dq__:${properties.loc_factor},__dq__prune_mode__dq__:__dq__${properties.prune_mode}__dq__,__dq__exclude_neighbors__dq__:${properties.exclude_neighbors},__dq__remove_tmp__dq__:${properties.remove_tmp},__dq__restart__dq__:${properties.restart}__cc____cc__'
  #end if

  #if str($input_matrix_path) != 'None':
    --input_matrix_path ${input_matrix_path}_`echo $$`.${input_matrix_path.ext}
  #end if

  #if str($input_top_path) != 'None':
    --input_top_path ${input_top_path}_`echo $$`.${input_top_path.ext}
  #end if

  #if str($input_contact_matrix_path) != 'None':
    --input_contact_matrix_path ${input_contact_matrix_path}_`echo $$`.${input_contact_matrix_path.ext}
  #end if


  --output_graph_path $outname_output_graph_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_matrix_path}_`echo $$`.${input_matrix_path.ext};

  rm -f ${input_top_path}_`echo $$`.${input_top_path.ext};

  rm -f ${input_contact_matrix_path}_`echo $$`.${input_contact_matrix_path.ext};


  if test -f $outname_output_graph_path; then mv $outname_output_graph_path $output_graph_path; fi;
